//! Reproducible TypeScript contract generator.
//!
//! Usage: `generate-types <output-path>`
//! The integration lane runs `mise run gen:ts` (which invokes `cargo run -p
//! mail-core --bin generate-types -- src/lib/ipc/generated.ts`). Output is
//! deterministic: fixed header, fixed declaration order, no timestamps. The
//! approved IPC command/event names are emitted alongside the DTOs so the
//! generated file is a drop-in replacement for the frontend transport seam.

use std::process::ExitCode;

use mail_core::dto::{
    Address, Conversation, ConversationRef, ConversationSummary, InboxSnapshot, Message,
    OperationFailure, OperationReceipt, OperationStatus, OperationSummary, SetArchived,
};
use mail_core::error::MailError;
use mail_core::gmail::types::{
    AccountInfo, AccountStatus, ConnectionState, MailMode, SyncInfo, SyncState,
};
use ts_rs::TS;

/// Declaration order matches the frozen wire contract in
/// `docs/vertical-slice-01.md`.
fn declarations() -> Vec<String> {
    vec![
        ConversationRef::decl(),
        Address::decl(),
        OperationStatus::decl(),
        OperationFailure::decl(),
        MailError::decl(),
        OperationReceipt::decl(),
        SetArchived::decl(),
        ConversationSummary::decl(),
        Message::decl(),
        Conversation::decl(),
        OperationSummary::decl(),
        InboxSnapshot::decl(),
        MailMode::decl(),
        ConnectionState::decl(),
        SyncState::decl(),
        AccountInfo::decl(),
        SyncInfo::decl(),
        AccountStatus::decl(),
    ]
}

const HEADER: &str = "// Generated by mail-core generate-types (ts-rs). Do not edit.\n\
// Contracts: docs/vertical-slice-01.md and docs/vertical-slice-02.md — camelCase fields, snake_case discriminants.\n\n";

/// Approved IPC surface names (docs/vertical-slice-01.md, "IPC commands").
const IPC_NAMES: &[(&str, &str)] = &[
    ("LIST_CONVERSATIONS_COMMAND", "list_conversations"),
    ("GET_CONVERSATION_COMMAND", "get_conversation"),
    ("SET_ARCHIVED_COMMAND", "set_archived"),
    ("MAILBOX_CHANGED_EVENT", "mailbox_changed"),
    ("GET_ACCOUNT_STATUS_COMMAND", "get_account_status"),
    ("CONNECT_ACCOUNT_COMMAND", "connect_account"),
    ("DISCONNECT_ACCOUNT_COMMAND", "disconnect_account"),
    ("REQUEST_SYNC_COMMAND", "request_sync"),
];

fn main() -> ExitCode {
    let Some(output_path) = std::env::args().nth(1) else {
        eprintln!("usage: generate-types <output-path>");
        return ExitCode::from(2);
    };
    let mut output = String::from(HEADER);
    for (constant, value) in IPC_NAMES {
        output.push_str(&format!("export const {constant} = '{value}';\n"));
    }
    output.push('\n');
    for declaration in declarations() {
        // ts-rs `decl()` emits a bare `type` alias; the transport seam re-exports
        // these names, so each declaration must be an `export type`.
        let declaration = declaration
            .strip_prefix("type ")
            .map(|rest| format!("export type {rest}"))
            .unwrap_or(declaration);
        for line in declaration.lines() {
            output.push_str(line.trim_end());
            output.push('\n');
        }
        output.push('\n');
    }
    if let Err(err) = std::fs::write(&output_path, output) {
        eprintln!("failed to write {output_path}: {err}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}
